-- MySQL sums text columns holding amounts (for example conceptos.gasto) by reading their
-- leading number (non-numeric text counts as 0; all NULL gives NULL). Same behaviour here.
CREATE OR REPLACE FUNCTION kualitet_text_sum_step(numeric, text) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN $2 IS NULL THEN $1 ELSE COALESCE($1, 0) + COALESCE(CAST(SUBSTRING(TRIM($2) FROM '^[-+]?[0-9]*\.?[0-9]+') AS numeric), 0) END $$;
DROP AGGREGATE IF EXISTS sum(varchar);
