ALTER SEQUENCE tipo_visita_id_tipo_seq OWNED BY tipo_visita.id_tipo;

CREATE SEQUENCE users_id_user_seq;
CREATE TABLE users (
    id_user bigint DEFAULT nextval('users_id_user_seq') NOT NULL,
    username varchar(50) COLLATE kualitet_ci,
    password varchar(255) COLLATE kualitet_ci,
    id_perfil integer NOT NULL,
    email varchar(100) COLLATE kualitet_ci NOT NULL,
    created timestamp(0) without time zone,
    modified timestamp(0) without time zone,
    PRIMARY KEY (id_user)
);
ALTER SEQUENCE users_id_user_seq OWNED BY users.id_user;

CREATE SEQUENCE users_condominio_id_seq;
CREATE TABLE users_condominio (
    id integer DEFAULT nextval('users_condominio_id_seq') NOT NULL,
    id_user integer NOT NULL,
    id_condominio integer NOT NULL,
    PRIMARY KEY (id)
);
ALTER SEQUENCE users_condominio_id_seq OWNED BY users_condominio.id;

CREATE SEQUENCE visitas_id_visita_seq;
CREATE TABLE visitas (
    id_visita integer DEFAULT nextval('visitas_id_visita_seq') NOT NULL,
    id_condominio integer,
    id_condomino integer,
    nombre varchar(255) COLLATE kualitet_ci NOT NULL,
    departamento varchar(45) COLLATE kualitet_ci,
    fecha date NOT NULL,
    hora time NOT NULL,
    tipo_visita varchar(45) COLLATE kualitet_ci NOT NULL,
    auto varchar(45) COLLATE kualitet_ci DEFAULT 'auto',
    color varchar(45) COLLATE kualitet_ci DEFAULT 'color',
    marca varchar(45) COLLATE kualitet_ci DEFAULT 'marca',
    placas varchar(45) COLLATE kualitet_ci DEFAULT 'placas',
    PRIMARY KEY (id_visita)
);
ALTER SEQUENCE visitas_id_visita_seq OWNED BY visitas.id_visita;

